import{_ as d,o as r,c as e,ag as a}from"./chunks/framework.KxDd3USm.js";const p=JSON.parse('{"title":"11.4 数据库、操作系统与网络词汇 ★★★","description":"","frontmatter":{},"headers":[],"relativePath":"11-专业英语/04-数据库操作系统与网络词汇.md","filePath":"11-专业英语/04-数据库操作系统与网络词汇.md"}'),o={name:"11-专业英语/04-数据库操作系统与网络词汇.md"};function n(i,t,c,l,s,h){return r(),e("div",null,[...t[0]||(t[0]=[a('<h1 id="_11-4-数据库、操作系统与网络词汇-★★★" tabindex="-1">11.4 数据库、操作系统与网络词汇 ★★★ <a class="header-anchor" href="#_11-4-数据库、操作系统与网络词汇-★★★" aria-label="Permalink to &quot;11.4 数据库、操作系统与网络词汇 ★★★&quot;">​</a></h1><h3 id="_4-1-数据库" tabindex="-1">4.1 数据库 <a class="header-anchor" href="#_4-1-数据库" aria-label="Permalink to &quot;4.1 数据库&quot;">​</a></h3><table tabindex="0"><thead><tr><th>English</th><th>中文</th><th>典型表达</th></tr></thead><tbody><tr><td>relation / tuple / attribute</td><td>关系 / 元组 / 属性</td><td>table / row / column</td></tr><tr><td>primary key / foreign key</td><td>主键 / 外键</td><td>uniquely identify / reference another table</td></tr><tr><td>constraint</td><td>约束</td><td>integrity constraint</td></tr><tr><td>normalization</td><td>规范化</td><td>reduce redundancy</td></tr><tr><td>redundancy</td><td>冗余</td><td>duplicated data</td></tr><tr><td>transaction</td><td>事务</td><td>a logical unit of work</td></tr><tr><td>atomicity</td><td>原子性</td><td>all or nothing</td></tr><tr><td>consistency</td><td>一致性</td><td>valid state to valid state</td></tr><tr><td>isolation</td><td>隔离性</td><td>concurrent transactions appear independent</td></tr><tr><td>durability</td><td>持久性</td><td>committed changes survive failures</td></tr><tr><td>concurrency control</td><td>并发控制</td><td>locks, serializability</td></tr><tr><td>commit / rollback</td><td>提交 / 回滚</td><td>make permanent / undo</td></tr><tr><td>query / retrieve</td><td>查询 / 检索</td><td>retrieve rows from a table</td></tr></tbody></table><p>ACID 识别句：</p><ul><li><code>either all operations occur or none do</code> → atomicity；</li><li><code>concurrent transactions do not interfere improperly</code> → isolation；</li><li><code>committed data survives a crash</code> → durability；</li><li><code>constraints remain satisfied</code> → consistency。</li></ul><h3 id="_4-2-操作系统" tabindex="-1">4.2 操作系统 <a class="header-anchor" href="#_4-2-操作系统" aria-label="Permalink to &quot;4.2 操作系统&quot;">​</a></h3><table tabindex="0"><thead><tr><th>English</th><th>中文</th></tr></thead><tbody><tr><td>process / thread</td><td>进程 / 线程</td></tr><tr><td>scheduling</td><td>调度</td></tr><tr><td>mutual exclusion</td><td>互斥</td></tr><tr><td>synchronization</td><td>同步</td></tr><tr><td>semaphore</td><td>信号量</td></tr><tr><td>deadlock / starvation</td><td>死锁 / 饥饿</td></tr><tr><td>virtual memory</td><td>虚拟存储</td></tr><tr><td>page fault</td><td>缺页</td></tr><tr><td>page replacement</td><td>页面置换</td></tr><tr><td>file system</td><td>文件系统</td></tr><tr><td>device driver</td><td>设备驱动程序</td></tr><tr><td>interrupt</td><td>中断</td></tr></tbody></table><p><code>process</code> 在操作系统中是“进程”，但作普通动词是“处理”。要用句子位置判断：<code>a running process</code> 是名词；<code>the server processes requests</code> 是动词。</p><h3 id="_4-3-网络" tabindex="-1">4.3 网络 <a class="header-anchor" href="#_4-3-网络" aria-label="Permalink to &quot;4.3 网络&quot;">​</a></h3><table tabindex="0"><thead><tr><th>English</th><th>中文</th><th>典型词组</th></tr></thead><tbody><tr><td>packet / frame / segment</td><td>分组 / 帧 / 报文段</td><td>network/data-link/transport layer</td></tr><tr><td>routing</td><td>路由选择</td><td>select a path</td></tr><tr><td>forwarding</td><td>转发</td><td>send to next hop</td></tr><tr><td>bandwidth</td><td>带宽</td><td>capacity per unit time</td></tr><tr><td>latency</td><td>时延</td><td>time taken to travel/respond</td></tr><tr><td>throughput</td><td>吞吐率</td><td>actual delivered rate</td></tr><tr><td>congestion</td><td>拥塞</td><td>too much traffic</td></tr><tr><td>reliable delivery</td><td>可靠交付</td><td>acknowledgment and retransmission</td></tr><tr><td>connection-oriented</td><td>面向连接</td><td>TCP</td></tr><tr><td>connectionless</td><td>无连接</td><td>UDP/IP</td></tr><tr><td>domain name resolution</td><td>域名解析</td><td>DNS</td></tr></tbody></table><p><strong>易错反例</strong>：bandwidth 和 throughput 不等价。Bandwidth 像公路理论车道容量，throughput 是实际每秒通过多少车；latency 是一辆车从起点到终点花多久。</p><p><strong>应试动作</strong>：数据库重点背 ACID 的英文定义；操作系统重点背 process/thread、deadlock、page fault；网络重点背 bandwidth/throughput/latency 三分法。</p><hr>',13)])])}const m=d(o,[["render",n]]);export{p as __pageData,m as default};
